def solve(s: str):
    """Run-length encoding: return list of [char, count] pairs for consecutive runs."""
    if not s:
        return []
    res = []
    cur = s[0]
    cnt = 1
    for ch in s[1:]:
        if ch == cur:
            cnt += 1
        else:
            res.append([cur, cnt])
            cur = ch
            cnt = 1
