import bisect

def solve(nums):
    """Return length of longest strictly increasing subsequence using O(n log n) method.
    Works for empty list as well.
    """
    tails = []  # tails[i] = smallest possible tail of an increasing subsequence of length i+1
    for x in nums:
        # Find position of first element >= x
        idx = bisect.bisect_left(tails, x)
        if idx == len(tails):
            tails.append(x)
        else:
            tails[idx] = x
    return len(tails)

