def solve(nums=None):
    """Return length of the longest strictly increasing subsequence.
    If called without arguments or with an empty iterable, returns 0.
    """
    if not nums:
        return 0
    import bisect
    tails = []
    for x in nums:
        i = bisect.bisect_left(tails, x)
        if i == len(tails):
            tails.append(x)
        else:
            tails[i] = x
    return len(tails)

