def solve(tokens):
    """Evaluate Reverse Polish Notation expression.
    tokens: list of strings containing integers or '+', '-', '*', '/'.
    Returns integer result, with division truncating toward zero.
    """
    stack = []
    for t in tokens:
        if t in '+-*/':
            b = stack.pop()
            a = stack.pop()
            if t == '+':
                stack.append(a + b)
            elif t == '-':
                stack.append(a - b)
            elif t == '*':
                stack.append(a * b)
            else:  # division
                # Truncate toward zero
                stack.append(int(a / b))
        else:
            stack.append(int(t))
    return stack[-1] if stack else 0

