def solve(intervals):
    # Filter out invalid interval entries
    if not intervals:
        return []
    valid = []
    for it in intervals:
        if isinstance(it, (list, tuple)) and len(it) >= 2:
            start, end = it[0], it[1]
            # ensure start <= end
            if start <= end:
                valid.append([start, end])
    if not valid:
        return []
    # Sort by start
    valid.sort(key=lambda x: x[0])
    merged = []
    cur_start, cur_end = valid[0]
    for start, end in valid[1:]:
        if start <= cur_end:  # overlap or touching
            cur_end = max(cur_end, end)
        else:
            merged.append([cur_start, cur_end])
            cur_start, cur_end = start, end
    merged.append([cur_start, cur_end])
    return merged

