import bisect

def solve(nums):
    """Return length of the longest strictly increasing subsequence.
    Uses patience sorting O(n log n).
    """
    if not isinstance(nums, list):
        return 0
    tail = []  # tail[i] = smallest possible tail of an inc subseq of length i+1
    for x in nums:
        # find position to replace
        i = bisect.bisect_left(tail, x)
        if i == len(tail):
            tail.append(x)
        else:
            tail[i] = x
    return len(tail)

