def solve(a: str, b: str) -> int:
    n, m = len(a), len(b)
    # Ensure the smaller string is b for memory efficiency (optional)
    dp = [[0]*(m+1) for _ in range(n+1)]
    for i in range(n+1):
        dp[i][0] = i
    for j in range(m+1):
        dp[0][j] = j
    for i in range(1, n+1):
        for j in range(1, m+1):
            if a[i-1] == b[j-1]:
                cost = 0
            else:
                cost = 1
            dp[i][j] = min(
                dp[i-1][j] + 1,      # deletion
                dp[i][j-1] + 1,      # insertion
                dp[i-1][j-1] + cost  # substitution
            )
    return dp[n][m]

def solve(a: str, b: str) -> int:
    """Space‑optimized Levenshtein distance.
    Uses O(min(len(a), len(b))) memory and runs in O(len(a)*len(b)) time.
    """
    # Ensure that b is the shorter string for less memory.
    if len(b) > len(a):
        a, b = b, a
    # Now len(b) <= len(a)
    previous = list(range(len(b) + 1))
    for i, ca in enumerate(a, 1):
        current = [i] + [0] * len(b)
        for j, cb in enumerate(b, 1):
            if ca == cb:
                current[j] = previous[j - 1]
            else:
                current[j] = 1 + min(previous[j],      # deletion
                                      current[j - 1],   # insertion
                                      previous[j - 1])   # substitution
        previous = current
    return previous[-1]

