def solve(nums):
    # classic DP O(n^2) version to be safe
    if not nums:
        return 0
    n=len(nums)
    dp=[1]*n
    for i in range(n):
        for j in range(i):
            if nums[j] < nums[i]:
                dp[i]=max(dp[i],dp[j]+1)
    return max(dp)

